import React from 'react';
import ReactDOM from 'react-dom/client';
import {useEffect, useState} from "react";
import { Provider } from 'react-redux';
import { useDispatch, useSelector } from "react-redux";

// Import global CSS
import '@/styles/global.css';

import { MantineProvider } from '@mantine/core';
import { overrideTheme } from '@/theme';
import { ModalsProvider } from '@mantine/modals';
import { Notifications } from '@mantine/notifications';
import { useMediaQuery } from "@mantine/hooks";
import { Center, Loader, useMantineTheme } from "@mantine/core";

import Viewer from "@/components/Viewer/Viewer";
import {createLogger, log_info} from "@/services/Logger";
import {HTTPRestAdaptor, RestAdaptor} from "@/adaptors/RestAdaptor";
import {Main} from "@/components/Main";
import {API_URL} from "@/domain/Constants";
import { AppDispatch, RootState } from "@/domain/Store";
import { setMode } from "@/domain/Store/ConfigReducer";
import { Mode } from "@/domain/Types";
import store from '@/domain/Store';


const host: RestAdaptor = new HTTPRestAdaptor();

createLogger(host);

function HomePage() {
  const dispatch: AppDispatch = useDispatch();
  const mode = useSelector((state: RootState) => state.config.mode);
  const theme = useMantineTheme();
  const isMobile = useMediaQuery(`(max-width: ${theme.breakpoints.sm})`);

  useEffect(() => {
    const userAgent = window.navigator.userAgent;
    const url = new URLSearchParams(location.search);

    if (url.has("player")) {
      log_info(`detected smart-tv: ${userAgent}, ${url}`);
      dispatch(setMode(Mode.Video));
    } else if(url.has("remote")) {
      dispatch(setMode(Mode.Remote));
    } else {
      dispatch(setMode(isMobile ? Mode.Remote : Mode.Video));
    }
  }, [isMobile])

  if (mode == Mode.Loading) {
    return <Center><Loader /></Center>;
  }
  else if (mode == Mode.Video || !isMobile) {
    return (<Viewer host={host}/>)
  } 
  else if (mode == Mode.Remote || isMobile) {
    return (<Main host={host}/>)
  } 
}

function App() {
  return (
    <Provider store={store}>
      <MantineProvider withCSSVariables withGlobalStyles withNormalizeCSS theme={overrideTheme}>
        <Notifications />
        <ModalsProvider>
          <HomePage />
        </ModalsProvider>
      </MantineProvider>
    </Provider>
  );
}

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);

root.render(<App/>); 