import { VideoDetails, RemotePlayerState } from "./Messages";
import { GetVideoName } from "./Utils";


export class VideoWrapper {
  private readonly video: VideoDetails;
  private readonly lastPlayerState?: RemotePlayerState;

  constructor(video: VideoDetails, lastPlayerState?: RemotePlayerState) {
    this.lastPlayerState = lastPlayerState;
    this.video = video;
  }

  name = (): string => {
    if (typeof this.video !== "undefined") {
      return this.video.video;
    }

    if (typeof this.lastPlayerState !== "undefined") {
      return this.lastPlayerState.video;
    }

    return "???";
  }

  displayName = (): string => {
    if (this.video) {
      return GetVideoName(this.video);
    }
    return this.name();
  }

  getCollection = (): string => {

    if (typeof this.video !== "undefined") {
      return this.video.collection;
    }

    if (typeof this.lastPlayerState !== "undefined") {
      return this.lastPlayerState.collection;
    }

    return "???";
  }

  getUrl = (): string => {
    /*
    this is a hack, we need the server to send the full url of the file to download 
    as the host with the media may not be the same as the host serving this app. 
    
    Also this code breaks if the root url changes 
    */
    const collection = this.getCollection();
    const downloadRoot = "/api/stream";

    if (collection !== "") {
      return `${downloadRoot}/${collection}/${this.name()}`;
    }

    return `${downloadRoot}/${this.name()}`;
  }

  showProgress = (): boolean => {
    const state = this.lastPlayerState;

    if (this.isCurrentlyPlaying()) {
      return true;
    }

    return state?.video == this.name() && state?.collection == this.getCollection()
  }

  getLastViewed = (): string => {
    if (typeof this.video !== "undefined") {
      return this.video?.lastViewed || "Never";
    }
    return "";
  }

  getPercentPlayed = (): number => {
    const state = this.lastPlayerState;

    let percentPlayed = 0
    if (state && state?.collection === this.video?.collection && state.video === this.video?.video) {
      percentPlayed = state.currentTime * 100 / state.duration;
    }
    if (typeof this.video !== "undefined" && (this.video?.playFrom || 0) > 0) {
      percentPlayed = (this.video?.playFrom || 0) * 100 / this.video?.metadata.duration;
    }

    if (percentPlayed > 97) {
      percentPlayed = 100;
    }

    return Math.round(percentPlayed);
  }

  isCurrentlyPlaying = (): boolean => {
    return typeof this.lastPlayerState !== "undefined";
  }

  getId = (): string => {
    return this.video?.checksum ?? this.lastPlayerState?.videoId ?? "";
  }

  getVideo = (): VideoDetails => {
    return this.video;
  }
}