import { AppDispatch, RootState } from "@/domain/Store";
import { setTvDisplayType } from "@/domain/Store/ConfigReducer";
import { ItemDisplayType } from "@/domain/Types";
import { SegmentedControl } from "@mantine/core";
import { FC } from "react";
import { useDispatch, useSelector } from "react-redux";

interface IDisplaySelector {
  size?: "xs" | "sm" | "md" | "lg" | "xl";
}

export const DisplaySelector: FC<IDisplaySelector> = ({ size = "xl" }) => {
  const dispatch: AppDispatch = useDispatch();
  const tvDisplayType = useSelector((state: RootState) => state.config.tvDisplayType);

  const setValue = (value: string) => {
    dispatch(setTvDisplayType(parseInt(value) as ItemDisplayType));
  }

  return <SegmentedControl
    size={size}
    color="blue"
    value={tvDisplayType.toString()}
    onChange={setValue}
    data={[
      { label: 'Carousel', value: ItemDisplayType.Carousel.toString() },
      { label: 'Grid', value: ItemDisplayType.Grid.toString() },
      { label: 'List', value: ItemDisplayType.List.toString() },
    ]}
  />;
}