import { ChildCollection, CollectionDetails, VideoDetails } from "./Messages";

export const getThumbnail = (thumbnails: string[] | undefined, width: number): string => {
  //const thumbnails: string[] = typeof thumbnail === "string" ? [thumbnail] : thumbnail;
  if (thumbnails && thumbnails.length > 0) {
    const thumbnail = thumbnails.find((t) => t.endsWith(`.${width}.jpg`));
    if (thumbnail) {
        return `/api/thumbnails/${thumbnail}`;
    } else {
        return `/api/thumbnails/${thumbnails[0]}`;
    }
  } 

  return "";
}


export const getThumbnailFromName = (name: string, width: number): string => {
  const lastDotIndex = name.lastIndexOf('.');
  if (lastDotIndex === -1) {
    return `/api/thumbnails/${name}.${width}.jpg`;
  }
  return `/api/thumbnails/${name.substring(0, lastDotIndex)}.${width}.jpg`;
}


export const getCleanName = (name: string) => {
  name = name.replaceAll(".", " ");
  // name.replace(/\[.*$/g, '');
  const pos = name.indexOf('[');
  return pos > -1 ? name.substring(0, pos) : name;
}

export const GetVideoName = (video: VideoDetails): string => {
  const episodeTitle = video?.series?.episodeTitle ?? "";
  const episode = video?.series?.episode ?? "";
  const season = video?.series?.season ?? "";
  if (episodeTitle !== "" && episode !== "" && season !== "") {
    return getCleanName(`${season}x${episode} - ${episodeTitle}`);
  } else if (episodeTitle !== "" && episode !== "") {
    return getCleanName(`${episode} - ${episodeTitle}`);
  } else if (episodeTitle !== "") {
    return getCleanName(episodeTitle);
  } else if (season !== "" && episode !== "") {
    return getCleanName(`Season ${season} Episode ${episode}`);
  }

  return getCleanName(video.video);
}

export interface CardSizes {
  imgWidth: number,
  imgHeight: number,
  footerHeight: number;
};

export const getCardSizes = (useSmallImages: boolean) => {
  const imgWidth = useSmallImages ? 480 : 720;
  const imgHeight = useSmallImages ? 300 : 450;
  const footerHeight = useSmallImages ? 64 : 64;

  return {
    imgWidth,
    imgHeight,
    footerHeight,
  }
}

export const getSeasons = (collection: CollectionDetails): ChildCollection[] => {
  let series: ChildCollection[] = [];

  for (const name of Object.keys(collection.series)) {
    const season: VideoDetails[] = collection.series[name] ?? [];
    if (!season.length) {
      continue;
    }

    series.push({
      collection: name,
      thumbnail: season[0].thumbnail,
    });
  }

  return series;
}

export const getCollectionsAndVideos = (activeSeries: CollectionDetails, currentSeason?: string) => {

  if (activeSeries.collection === "") {
    return {
      child_collections: activeSeries.child_collections, 
      videos: activeSeries.videos
    };
  }

  if (typeof currentSeason !== "undefined") {
    return {
      child_collections: [],
      videos: activeSeries.series[currentSeason] || []
    };
  }

  const seasons = getSeasons(activeSeries);
  if (!seasons.length) {
    return {
      child_collections: [],
      videos: activeSeries.videos
    };
  }

  if (seasons.length === 1 && seasons[0].collection === "") {
    return {
      child_collections: [],
      videos: activeSeries.series[seasons[0].collection] || []
    };
  }

  return {
    child_collections: getSeasons(activeSeries),
    videos: [] //activeSeries.series?.[""] ?? [],
  };
}
