import React, { FC, useEffect, useState } from "react";
import { Box, Center, Text, useMantineTheme } from "@mantine/core";

interface AnalogClockProps {
  size?: number;
  hourHandColor?: string;
  minuteHandColor?: string;
  secondHandColor?: string;
  dialColor?: string;
  dialOpacity?: number;
  digitalTimeFormat?: "12h" | "24h";
  digitalTimeSizeFactor?: number;
}

// Utility function to convert rem to pixels
export const remToPx = (remValue: number | string): number => {
  // Default root font size (typically 16px)
  const defaultRootFontSize = 16;
  
  // Convert string rem to number if needed
  const rem = typeof remValue === 'string' 
    ? parseFloat(remValue.replace('rem', '')) 
    : remValue;
  
  try {
    // Try to get the computed font size if in browser environment
    if (typeof window !== 'undefined' && document.documentElement) {
      const rootFontSize = parseFloat(
        getComputedStyle(document.documentElement).fontSize
      );
      return rem * (rootFontSize || defaultRootFontSize);
    }
  } catch (e) {
    console.warn("Error calculating rem to px, using default conversion", e);
  }
  
  // Fallback to default conversion
  return rem * defaultRootFontSize;
};

export const AnalogClock: FC<AnalogClockProps> = ({
  size = 240,
  hourHandColor = "#FFFFFF",
  minuteHandColor = "#FFFFFF",
  secondHandColor = "#FFFFFF",
  dialColor,
  dialOpacity = 0.7,
  digitalTimeFormat = "24h",
  digitalTimeSizeFactor = 8,
}) => {
  const theme = useMantineTheme();
  const [time, setTime] = useState(new Date());

  // Use theme primary color for dial if not provided
  const primaryColor = theme.colors[theme.primaryColor][6];
  const finalDialColor = dialColor || primaryColor;
  
  // Add opacity to the dial color if it doesn't already have one
  const dialColorWithOpacity = finalDialColor.includes('rgba') 
    ? finalDialColor 
    : finalDialColor.replace('rgb', 'rgba').replace(')', `, ${dialOpacity})`);

  useEffect(() => {
    const intervalId = setInterval(() => {
      setTime(new Date());
    }, 1000);

    return () => clearInterval(intervalId);
  }, []);

  // Calculate hand angles
  const hours = time.getHours() % 12;
  const minutes = time.getMinutes();
  const seconds = time.getSeconds();

  const hourAngle = (hours * 30) + (minutes * 0.5); // 30 degrees per hour + adjustment for minutes
  const minuteAngle = minutes * 6; // 6 degrees per minute
  const secondAngle = seconds * 6; // 6 degrees per second

  // Format digital time
  const formatDigitalTime = () => {
    let hours = time.getHours();
    const minutes = time.getMinutes().toString().padStart(2, '0');
    const seconds = time.getSeconds().toString().padStart(2, '0');
    
    if (digitalTimeFormat === "12h") {
      const period = hours >= 12 ? "PM" : "AM";
      hours = hours % 12 || 12; // Convert 0 to 12 for 12 AM
      return `${hours}:${minutes}:${seconds} ${period}`;
    } else {
      return `${hours.toString().padStart(2, '0')}:${minutes}:${seconds}`;
    }
  };

  // Clock face constants
  const center = size / 2;
  const radius = size / 2 - 10;
  const hourHandLength = radius * 0.5;
  const minuteHandLength = radius * 0.7;
  const secondHandLength = radius * 0.8;

  // Calculate digital time panel width based on clock size
  const digitalPanelWidth = size * 0.9;
  const digitalFontSize = size / digitalTimeSizeFactor;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <Center mb={5}>
        <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          {/* Clock dial */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill={dialColorWithOpacity}
            stroke="#333333"
            strokeWidth="2"
          />

          {/* Hour markers */}
          {[...Array(12)].map((_, i) => {
            const angle = (i * 30) * (Math.PI / 180);
            const x1 = center + (radius - 10) * Math.sin(angle);
            const y1 = center - (radius - 10) * Math.cos(angle);
            const x2 = center + radius * Math.sin(angle);
            const y2 = center - radius * Math.cos(angle);
            
            return (
              <line
                key={i}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke="#FFFFFF"
                strokeWidth={i % 3 === 0 ? "4" : "2"}
                strokeLinecap="round"
              />
            );
          })}

          {/* Hour hand */}
          <line
            x1={center}
            y1={center}
            x2={center + hourHandLength * Math.sin(hourAngle * (Math.PI / 180))}
            y2={center - hourHandLength * Math.cos(hourAngle * (Math.PI / 180))}
            stroke={hourHandColor}
            strokeWidth="4"
            strokeLinecap="round"
          />

          {/* Minute hand */}
          <line
            x1={center}
            y1={center}
            x2={center + minuteHandLength * Math.sin(minuteAngle * (Math.PI / 180))}
            y2={center - minuteHandLength * Math.cos(minuteAngle * (Math.PI / 180))}
            stroke={minuteHandColor}
            strokeWidth="3"
            strokeLinecap="round"
          />

          {/* Second hand */}
          <line
            x1={center}
            y1={center}
            x2={center + secondHandLength * Math.sin(secondAngle * (Math.PI / 180))}
            y2={center - secondHandLength * Math.cos(secondAngle * (Math.PI / 180))}
            stroke={secondHandColor}
            strokeWidth="1.5"
            strokeLinecap="round"
          />

          {/* Center dot */}
          <circle
            cx={center}
            cy={center}
            r="5"
            fill={secondHandColor}
          />
        </svg>
      </Center>

      {/* Digital time panel with matching background */}
      <Box 
        sx={{
          backgroundColor: dialColorWithOpacity,
          padding: `${size/30}px ${size/15}px`,
          borderRadius: size/20,
          width: digitalPanelWidth,
          textAlign: 'center',
          border: '2px solid #333333',
        }}
      >
        <Text 
          size={digitalFontSize} 
          weight={600}
          sx={{ lineHeight: 1.2, color: "#FFFFFF" }}
        >
          {formatDigitalTime()}
        </Text>
      </Box>
    </Box>
  );
}; 