import React, {useEffect, useReducer, useRef } from "react";
import { Affix, AspectRatio, Box, Modal, rem, Transition } from "@mantine/core";
import { useDebouncedState } from "@mantine/hooks";
import { useSelector } from "react-redux";
import { PlayRequest, RemoteMessage, VideoDetails} from "@/domain/Messages";
import { RootState } from "@/domain/Store";
import { SocketAdaptor } from "@/adaptors/Socket";
import { RestAdaptor } from "@/adaptors/RestAdaptor";
import  {VideoPlayer } from "@/services/Player";
import { useTabVisibility } from "@/services/helpers";
import { Controls } from "./Controls";
import { Picker } from "./Picker";
import Player, { PlayState, PlayerHandlers } from './Player';

type VideoControlProps = {
  host: RestAdaptor;
}

interface IVideoState {
  showVideoSelection: boolean;
  currentVideo?: PlayRequest;
  currentCollection: string;
  wasPlaying: boolean;
  isPlaying: boolean;
  socket: SocketAdaptor | null;
}

type Action =
  | { type: 'SET_SHOW_VIDEO_SELECTION'; payload: boolean }
  | { type: 'SET_CURRENT_VIDEO'; payload: PlayRequest | undefined }
  | { type: 'SET_CURRENT_COLLECTION'; payload: string }
  | { type: 'SET_SOCKET'; payload: SocketAdaptor | null }
  | { type: 'SET_IS_PLAYING'; payload: boolean } 
  | { type: 'SET_WAS_PLAYING'; payload: boolean };

const initialState: IVideoState = {
  showVideoSelection: true,
  currentVideo: undefined,
  currentCollection: '',
  wasPlaying: false,
  isPlaying: false,
  socket: null
};

function reducer(state: IVideoState, action: Action): IVideoState {
  switch (action.type) {
    case 'SET_SHOW_VIDEO_SELECTION':
      return { ...state, showVideoSelection: action.payload };
    case 'SET_CURRENT_VIDEO':
      return { ...state, currentVideo: action.payload };
    case 'SET_WAS_PLAYING':
      return { ...state, wasPlaying: action.payload };
    case 'SET_IS_PLAYING':
        return { ...state, isPlaying: action.payload };
    case 'SET_SOCKET':
      return { ...state, socket: action.payload };
    default:
      return state;
  }
}

const Viewer = (props: VideoControlProps) => {

  const videoControlRef = useRef<PlayerHandlers | null>(null);
  const [state, dispatch] = useReducer(reducer, initialState);
  const [debouncedShowControls, setDebouncedShowControls] = useDebouncedState(true, 200);
  const mode = useSelector((state: RootState) => state.config.mode);  
  const videoPlayer = new VideoPlayer(props.host, "");

  const seek = (interval: number) => {
    if (videoControlRef.current !== null) {
      videoControlRef.current.seek(interval);
    }
  }

  useEffect(() => {
    SocketAdaptor.CloseAll();
    const socketUrl = props.host.getSocketHost(location.host, location.protocol, "api/remote/ws");
    const _socket = new SocketAdaptor(
      () => {
        console.log(`connecting to: ${socketUrl}`);
        return new WebSocket(socketUrl);
      },
      (message: RemoteMessage) => {
        if (typeof message.Play !== "undefined") {
          dispatch({ type: 'SET_CURRENT_VIDEO', payload: message.Play });
          
        } else if (typeof message.Seek !== "undefined" && videoControlRef !== null) {
          seek(message.Seek.interval);

        } else if (typeof message.TogglePause !== "undefined" && videoControlRef !== null) {
          videoControlRef.current?.pause();
        }
      }
    );

    dispatch({ type: 'SET_SOCKET', payload: _socket});

  }, [props.host, mode]);

  useTabVisibility((newState: string) => {
    if (state.socket === null) {
      return;
    }

    switch (newState) {
      case "visible":
        state.socket.retryReconnect();
        if (state.wasPlaying) {
          dispatch({ type: 'SET_WAS_PLAYING', payload: false });
          videoControlRef.current?.pause();
        }
        break;
      case "hidden":
        if (videoControlRef.current?.isPlaying()) {
          dispatch({ type: 'SET_WAS_PLAYING', payload: true });
          videoControlRef.current?.pause(); 
        }
    }
  });

  const showControls = (show: boolean) => {
    dispatch({ type: 'SET_SHOW_VIDEO_SELECTION', payload: show });
    setDebouncedShowControls(show);
  }

  const onStateChange = (newState: PlayState) => {
    console.log(`state change: ${newState}`);
    switch (newState) {
      case PlayState.STARTED:
        console.log("onStateChange: started");
        showControls(false);
        dispatch({ type: 'SET_IS_PLAYING', payload: true });
        break;
      case PlayState.PAUSED:     
      case PlayState.STOPPED:
        console.log("onStateChange: stopped/paused");
        dispatch({ type: 'SET_IS_PLAYING', payload: false });
        if (!debouncedShowControls) {
          console.log("hiding video");
          //showControls(true);
        }
    }
  }

  const onCloseDraw = () => {
    if (typeof state.currentVideo === "undefined") {
      return;
    }
    if (!videoControlRef.current?.isPlaying()) {
      videoControlRef.current?.pause(); 
    }
    showControls(false);
  }

  let player = (<></>);
  let osd = (
    !debouncedShowControls &&
    <Controls 
      seek={seek} 
      isPlaying={videoControlRef.current?.isPlaying}
      currentlyPlaying={state.isPlaying}
      togglePause={videoControlRef.current?.pause}
      quit={() => showControls(true)}
    />
  )
 
  if (typeof state.currentVideo !== "undefined") {
    player = (
      <>
        <AspectRatio 
          ratio={state.currentVideo.aspectWidth / state.currentVideo.aspectHeight}
          sx={{ width: '100%', height: '100%' }}
        >
          <Player 
            currentVideo={state.currentVideo} 
            socket={state.socket} 
            ref={videoControlRef} 
            onStateChange={onStateChange}
          />
        </AspectRatio>
        { osd }
      </>
    )
  };

  // Always render the Picker but control visibility with the prop
  const controls = (
    <Picker 
      videoPlayer={videoPlayer} 
      togglePause={videoControlRef.current?.pause}
      visible={debouncedShowControls}
    />
  );

  return (
    <Box sx={{ backgroundColor: '#000000', position: 'fixed', top: 0, left: 0, right: 0, bottom: 0 }}>
      {player}
      {controls}
    </Box>
  );
};

export default Viewer;