import VideoTab from "./Video/VideoTab";
import {SearchTab} from "./Search/SearchTab";
import {TasksTab} from "./Tasks/TasksTab";
import {HostConfig, RemoteMessage, VideoDetails} from "../domain/Messages";
import React, {useEffect, useState} from "react";
import {VideoPlayer} from "../services/Player";
import {Alert, gAlertManager} from "./Base/Alert";
import { CardModal } from "./Base/Modal"
import {SocketAdaptor} from "../adaptors/Socket";
import {VideoItemDetail} from "./Video/VideoDetail";
import {SpeedDialer} from "./SpeedDialer";
import { useTabVisibility } from "@/services/helpers";
import { Container, Portal, ScrollArea, createStyles } from "@mantine/core";
import { useDispatch, useSelector } from 'react-redux';
import { handleRemotePlayerState } from "@/domain/Store/EventReducer";
import { CurrentlyPlayingDetails } from "./Video/CurrentlyPlayingDetails";
import { AppDispatch, RootState } from "@/domain/Store";
import { Mode } from "@/domain/Types";

// Create styles using Mantine's createStyles
const useStyles = createStyles((theme) => ({
  mainContainer: {
    padding: '0.5rem'
  }
}));

enum CardNames {
  Videos,
  CurrentVideo,
  Search,
  Tasks,
  VideoDetail,
}

/**
 * The main component of the application.
 * @param {HostConfig} props - The host configuration.
 */
export const Main = (props: HostConfig) => {
  const { classes } = useStyles();
  const [socket, setSocket] = useState<SocketAdaptor | null>(null);
  const [activeCard, setActiveCard] = useState<CardNames>(CardNames.Videos);
  const [alertVisible, setAlertVisible] = useState<boolean>(false);
  const [dialog, setDialog] = useState<JSX.Element>((<></>));
  const [currentVideo, setCurrentVideo] = useState<VideoDetails | null>(null);
  const mode = useSelector((state: RootState) => state.config.mode);
  const videoPlayer = new VideoPlayer(props.host, "");
  const dispatch = useDispatch<AppDispatch>();

  useEffect(() => {
    const socketUrl = props.host.getSocketHost(location.host, location.protocol, "api/control/ws");
    const webSocketFactory = () => {
      console.log(`connecting to: ${socketUrl}`);
      return new WebSocket(socketUrl)
    };
    SocketAdaptor.CloseAll();
    setSocket(new SocketAdaptor(
      webSocketFactory, (message: RemoteMessage) => {
        dispatch(handleRemotePlayerState(message));
      }
    ));
  }, [props.host, mode]);

  useTabVisibility((newState: string) => {
    if (newState === "visible" && socket !== null) {
        socket.retryReconnect();
    }
  });

  const showVideoDetails = (video: VideoDetails) => {
    setCurrentVideo(video);
    setActiveCard(CardNames.VideoDetail);
  }

  // Determine which component to render based on the active tab.
  const getMainCard = () => {
    const onClose = () => setActiveCard(CardNames.Videos);

    switch (activeCard) {
      case CardNames.Search:
        return (
          <CardModal title={"Search"} onClose={onClose}>
            <SearchTab host={props.host} />
          </CardModal>
        );

      case CardNames.Tasks:
        return (
          <CardModal title="Running Tasks" onClose={onClose}>
            <TasksTab host={props.host} isActive={true} />
          </CardModal>
        );

      case CardNames.CurrentVideo:
        return (
          <CardModal title="Current Video" onClose={onClose}>
            <CurrentlyPlayingDetails
              player={videoPlayer}
              setDialog={setDialog}
              back={onClose}
            />
          </CardModal>
        );
        
      case CardNames.VideoDetail:
        if (currentVideo !== null) {
          const onClose = () => {
            setCurrentVideo(null);
            setActiveCard(CardNames.Videos);
          }

          return (
            <CardModal title="Video Details" onClose={onClose}>
              <VideoItemDetail
                video={currentVideo}
                setDialog={setDialog}
                back={() => setCurrentVideo(null)}
                player={videoPlayer}
              />
            </CardModal>
          );
        }
    }

    return (<></>);
  };

  // Set the alert visibility state based on the global alert manager.
  gAlertManager.setStateFunction(setAlertVisible);

  return (
    <>
    <Container px="xs" py="xs" className={classes.mainContainer}>
      { getMainCard() }

      { dialog }

      {/* Render the selected main component*/}
      <ScrollArea>
        <VideoTab
          videoPlayer={videoPlayer}
          isActive={activeCard === CardNames.Videos}
          showVideoDetails={showVideoDetails}
        />
      </ScrollArea>

      <SpeedDialer
        showCurrentVideo={() => setActiveCard(CardNames.CurrentVideo)}
        showSearch={() => setActiveCard(CardNames.Search)}
        showTasks={() => setActiveCard(CardNames.Tasks)}
      />

    </Container>
      {/* Render the global alert component. */}
      <Portal>
        <Alert show={alertVisible}/>
      </Portal>
    </>
  )
}
