import { FC, useEffect } from "react";
import {Player} from "../../services/Player";
import {VideoList} from "./VideoList";
import { VideoGrid } from "./VideoGrid";
import { VideoCarousel } from "./VideoCarousel";
import { fetchSeriesDetails } from "@/domain/Store/SeriesReducer";
import { AppDispatch, RootState } from "@/domain/Store";
import { useDispatch, useSelector } from "react-redux";
import { ItemDisplayType } from "@/domain/Types";
import { VideoDetails } from "@/domain/Messages";
import { useMantineTheme } from "@mantine/core";
import { useMediaQuery } from "@mantine/hooks";


/**
 * Represents the configuration object for the VideoSelection component
 * @typedef {Object} VideoConfig
 * @property {VideoPlayer} videoPlayer - The video player service used for playing videos
 * @property {boolean} isActive - Whether the VideoSelection is active or not
 */
export interface IVideoSelectionConfig {
  videoPlayer: Player;
  isActive: boolean;
  showVideoDetails?: (video: VideoDetails) => void;
}

/**
 * Represents the VideoSelection component
 * @function
 * @param {IVideoConfig} props - Config object for the VideoSelection component
 * @returns {JSX.Element} - The VideoSelection component's UI
 */
const VideoSelection: FC<IVideoSelectionConfig> = ({videoPlayer, isActive, showVideoDetails}) => {
  const dispatch: AppDispatch = useDispatch();
  const seriesState = useSelector((state: RootState) => state.series);
  const config = useSelector((state: RootState) => state.config);
  const theme = useMantineTheme();
  const isMobile = useMediaQuery(`(max-width: ${theme.breakpoints.sm})`);
  const displayType = isMobile ? config.mobileDisplayType : config.tvDisplayType;

  const activeSeries = seriesState.activeSeries;
  
  useEffect(() => {
    // Fetch data and set interval to re-fetch data periodically when component is active
    if (isActive && typeof activeSeries === "undefined" && !seriesState.loadingResults) {
      dispatch(fetchSeriesDetails(""));
    }
  }, [activeSeries, videoPlayer, isActive])

  //return <VideoGrid videoPlayer={videoPlayer} />;

  const items = (() => {
    switch (displayType) {
      case ItemDisplayType.Carousel:
        return <VideoCarousel videoPlayer={videoPlayer}/>;
      case ItemDisplayType.Grid:
        return <VideoGrid videoPlayer={videoPlayer} />;
      case ItemDisplayType.List:
        return <VideoList videoPlayer={videoPlayer} showVideoDetails={showVideoDetails} />;
    }
  })();

  // Render VideoSelection UI
  return items;
}

export default VideoSelection;