import { getCleanName } from "@/domain/Utils";
import { List, Flex, Burger, Text, Menu, createStyles, Group } from "@mantine/core";
import { useDisclosure } from "@mantine/hooks";

// Remove the SCSS module import and use Mantine's createStyles
import { IconShare, IconSearch } from "@tabler/icons-react";
import { FC } from "react";
import { Player } from "@/services/Player";

// Create styles using Mantine's createStyles
const useStyles = createStyles((theme) => ({
  listItem: {
    cursor: 'pointer',
    transition: 'background-color 0.2s',
    '&:hover': {
      backgroundColor: theme.colorScheme === 'dark' 
        ? theme.fn.rgba(theme.colors.dark[5], 0.1)
        : theme.fn.rgba(theme.colors.gray[0], 0.3)
    }
  },
  burgerIcon: {
    position: 'absolute',
    right: "1rem",
  }
}));

interface ICollectionItem {
  isLast: boolean;
  name: string;
  collection?: string;
  onClick: () => void;
  player: Player;
}

enum MenuAction {
  SHARE,
  DELETE
}

/**
 * CollectionItem component, used to display each collection item
 * 
 * @param {ICollectionItem} props - object containing the attributes of the collection item to be displayed
 * 
 * @returns {JSX.Element} - returns a JSX element containing the collection item to be displayed
 */
export const CollectionItem: FC<ICollectionItem> = ({isLast, name, collection, onClick, player}): JSX.Element => {
  const { classes } = useStyles();
  const [opened, { toggle }] = useDisclosure(false);
  const key = collection ? `${collection}/${name}` : name;
  const displayName = name !== "" ? getCleanName(name) : "Others";

  const handleBurgerClick = (event: React.SyntheticEvent) => {
    toggle();
    event.stopPropagation(); // Prevent the list item click event from firing
  };

  const handleMenuClick = (action: MenuAction) => {
    switch (action) {
      case MenuAction.SHARE:
        player.shareVideo(name, key);
        break;
      case MenuAction.DELETE:
        player.deleteVideo(name, key);
        break;
    }
  }

  const handleItemClick = (event: React.SyntheticEvent) => {
    if (!opened) {
      onClick();
      event.stopPropagation();
    }
  }

  // <Flex justify="space-between" align="flex-start">

  return (
    <CollectionMenu opened={opened} toggle={toggle} onMenuClick={handleMenuClick}>
      <List.Item onClick={handleItemClick} className={classes.listItem}>
        <Group position="apart">
          <Text>{displayName}</Text>
          <Burger
            opened={opened}
            className={classes.burgerIcon}
            size="xs"
            onClick={(event) => handleBurgerClick(event)}
          />
        </Group>
      </List.Item>
    </CollectionMenu>
  );
}

interface ICollectionMenu {
  children?: React.ReactNode;
  opened: boolean;
  toggle: () => void;
  onMenuClick: (action: MenuAction) => void;
}


const CollectionMenu: FC<ICollectionMenu> = ({children, opened, toggle, onMenuClick}) => {
  return (
    <Menu opened={opened} onChange={toggle} shadow="md" width={200} withArrow withinPortal>
      <Menu.Target>
        {children}
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Item onClick={() => onMenuClick(MenuAction.SHARE)} icon={<IconShare size={14} />}>Share</Menu.Item>
        <Menu.Divider />
        <Menu.Item
          onClick={() => onMenuClick(MenuAction.DELETE)}
          icon={<IconSearch size={14} />}
          rightSection={<Text size="xs" color="dimmed">⌘K</Text>}
        >
          Delete
        </Menu.Item>
      </Menu.Dropdown>
    </Menu>
  );
}
