/* eslint-disable @next/next/no-img-element */
import { Player } from "../../services/Player";
import {Progress, Stack, Text, Center } from "@mantine/core";
import React, {Dispatch, FC, SetStateAction} from "react";
import {RemotePlayerState } from "../../domain/Messages";
import {secondsToHMSString} from "../../services/helpers";
import { useDispatch, useSelector } from "react-redux";
import { AppDispatch, RootState } from "@/domain/Store";
import { VideoWrapper } from "@/domain/VideoWrapper";

import { fetchVideoDetails } from "@/domain/Store/SeriesReducer";
import { VideoItemDialogDetail } from "./VideoDetailDialog";

interface CurrentlyPlayingDetailsProps {
  player: Player;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: (() => void);
}

export const CurrentlyPlayingDetails: FC<CurrentlyPlayingDetailsProps> = ({player, setDialog, back}) => {
  const dispatch: AppDispatch = useDispatch();
  const lastPlayerState = useSelector((state: RootState) => state.remote.lastState);
  const loading = useSelector((state: RootState) => state.series.loadingPlaying);
  const video = useSelector((state: RootState) => state.series.playing);

  if (!lastPlayerState) {
    return <Text>Nothing is playing</Text>;
  }
  
  if (!loading && lastPlayerState?.videoId !== video?.checksum) {
    dispatch(fetchVideoDetails(lastPlayerState.videoId));
  }

  if (!video) {
    return <Text>Loading</Text>;
  }

  const helper = new VideoWrapper(video, lastPlayerState);
  const description = <PlayerProgress playerState={lastPlayerState} />;

  return <VideoItemDialogDetail 
    helper={helper}
    player={player}
    description={description}
    setDialog={setDialog}
    back={back}
  />
}

export const PlayerProgress:React.FC<{playerState?: RemotePlayerState}> = ({playerState}) => {

  if (typeof playerState === "undefined") {
    return (<></>);
  }

  const percent_done = playerState.currentTime * 100 / playerState.duration;
  const time_str = secondsToHMSString(playerState.currentTime);
  const duration_str = secondsToHMSString(playerState.duration);
  const progress =  `${ time_str } / ${ duration_str }`;

  return <Stack>
    <Progress w="100%" size="xl" radius="xl" value={percent_done} />
    <Center><Text>{progress}</Text></Center>
  </Stack>
}
