/**
 * Function to display a question alert box.
 * 
 * @param message - Message   be displayed in the alert box.
 * @param onOk - Callback function to be executed when the user clicks on the 'Ok' button of the alert box.
 */
export const askQuestion = (message: string, onOk?: (() => void)) => {
  showAlert(message, AlertType.Question, onOk);
}

/**
 * Function to display an alert box.
 * 
 * @param message - Message to be displayed in the alert box.
 * @param type - Type of the alert box.
 * @param onOk - Callback function to be executed when the user clicks on the 'Ok' button of the alert box.
 */
const showAlert = (message: string, type: AlertType, onOk?: (() => void)) => {
  modals.openConfirmModal({
    title: 'Please confirm your action',
    children: (
      <Text size="sm">
        {message}
      </Text>
    ),
    labels: { confirm: 'OK', cancel: 'Cancel' },
    onCancel: () => console.log('Cancel'),
    onConfirm: onOk,
  });
}

/**
 * Interface representing the configuration of the Alert component.
 */
type AlertConfig = {
  /**
   * Boolean value indicating whether the alert box is visible or hidden.
   */
  show: boolean;
}

/**
 * Component representing an alert box.
 * 
 * @param props - Configuration object for the Alert component.
 */
export const Alert = (props: AlertConfig) => {
  let icon;
  let extraButton = null;

  if (gAlertManager.type === AlertType.Information) {
    icon = (<HiOutlineInformationCircle color="green" size="3rem" />);
  } else if (gAlertManager.type === AlertType.Error) {
    icon = (<HiOutlineExclamationCircle color="red" size="3rem" />);
  } else if (gAlertManager.type === AlertType.Question) {
    icon = (<HiOutlineQuestionMarkCircle color="blue" size="3rem"  />);
    extraButton = (
      <Button variant="outline" color="blue" onClick={() => gAlertManager.hideAlert()}>
        Cancel
      </Button>
    )
  } else {
    icon = (<HiExclamation color="yellow" size="3rem"/>);
  }

  return (
    <div style={{zIndex: 2090}}>
      <Modal opened={props.show} withCloseButton onClose={() => gAlertManager.hideAlert()}>
        <Stack>
          <Center><ActionIcon variant="transparent" size="xl">{ icon }</ActionIcon></Center>
          <Text>{gAlertManager.message}</Text>
          <Group position="center">
            <Button onClick={() => gAlertManager.okClicked()}>OK</Button>
            { extraButton }
          </Group>
        </Stack>
      </Modal>
    </div>
  )
}

