import { FC } from "react";
import {Player} from "../../services/Player";
import { BackButton } from "./BackButton";
import VideoSelection from "./VideoSelection";
import { VideoDetails } from "@/domain/Messages";
/**
 * Represents the configuration object for the VideoTab component
 * @typedef {Object} VideoConfig
 * @property {VideoPlayer} videoPlayer - The video player service used for playing videos
 * @property {boolean} isActive - Whether the VideoTab is active or not
 */
export interface IVideoConfig {
  videoPlayer: Player;
  isActive: boolean;
  showVideoDetails: (video: VideoDetails) => void;
}

/**
 * Represents the VideoTab component
 * @function
 * @param {IVideoConfig} props - Config object for the VideoTab component
 * @returns {JSX.Element} - The VideoTab component's UI
 */
const VideoTab: FC<IVideoConfig> = ({videoPlayer, isActive, showVideoDetails}) => {
  // Render VideoTab UI
  return <>
    <BackButton size="sm"/>
    <VideoSelection 
      videoPlayer={videoPlayer} 
      isActive={isActive} 
      showVideoDetails={showVideoDetails} 
    />
  </>;
}

export default VideoTab;