import { createSlice, PayloadAction } from "@reduxjs/toolkit";
import { ItemDisplayType, Mode } from "../Types";


interface ConfigState {
  tvDisplayType: ItemDisplayType;
  mobileDisplayType: ItemDisplayType;
  mode: Mode;
  remotePlayer?: string;
}

const initialState: ConfigState = {
    tvDisplayType: ItemDisplayType.Grid,
    mobileDisplayType: ItemDisplayType.List,
    mode: Mode.Loading,
};

export const configSlice = createSlice({
  name: 'config',
  initialState,
  reducers: {
    setTvDisplayType: (state, action: PayloadAction<ItemDisplayType>) => {
      state.tvDisplayType = action.payload;
    },
    setMobileDisplayType: (state, action: PayloadAction<ItemDisplayType>) => {
      state.mobileDisplayType = action.payload;
    },
    setRemotePlayer: (state, action: PayloadAction<string>) => {
        state.remotePlayer = action.payload;
    },
    setMode: (state, action: PayloadAction<Mode>) => {
        state.mode = action.payload;
    }
  },
});

export const { setTvDisplayType, setMobileDisplayType, setMode } = configSlice.actions;

export default configSlice.reducer;
