import { VideoDetailsImpl } from "@/domain/Models";
import { log_error } from "@/services/Logger";
import { Stack, SimpleGrid, Text } from "@mantine/core";

export const getDescription = (videoDetails: VideoDetailsImpl | null) => {
    try {
      return (
        <Stack>
          <SimpleGrid cols={2} verticalSpacing={0}>
            <Text size="sm">Duration:</Text><Text size="sm">{videoDetails?.getDuration() || "?"}</Text>
            <Text size="sm">Size:</Text><Text size="sm">{videoDetails?.getSize() || "?"}</Text>
            <Text size="sm">Last Viewed:</Text><Text size="sm">{videoDetails?.lastViewed || "Never"}</Text>
          </SimpleGrid>
        </Stack>
      );
      // <Text size="sm" color="dimmed">{videoDetails?.description || ""}</Text>
    } catch(error) {
      log_error(error, `getDescription: ${videoDetails}`);
      return (
        <Text size="sm">
          { JSON.stringify(error) }
        </Text>
      )
    }
  }
  