import { Player } from "../../services/Player";
import { Text } from "@mantine/core";
import React, {Dispatch, FC, SetStateAction} from "react";
import {VideoDetails} from "../../domain/Messages";
import {VideoDetailsImpl} from "../../domain/Models";
import { VideoWrapper } from "@/domain/VideoWrapper";
import { getDescription } from "./Utils";
import { VideoItemDialogDetail } from "./VideoDetailDialog";

interface VideoDetailProps {
  video: VideoDetails;
  player: Player;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: (() => void);
}

export const VideoItemDetail: FC<VideoDetailProps> = ({video, player, setDialog, back}) => {
  const helper = new VideoWrapper(video);

  const description = video ? getDescription(new VideoDetailsImpl(video)) : <Text>Loading...</Text>;

  return <VideoItemDialogDetail 
    helper={helper}
    player={player}
    description={description}
    setDialog={setDialog}
    back={back}
  />
}
