const remoteMessageSlice = createSlice({
  name: 'remote',
  initialState,
  reducers: {
    dispatchRemoteMessage: (state, action: PayloadAction<RemoteMessage>) => {
      if (action.payload.Play) {
        state.lastPlayRequest = action.payload.Play;
      }
      if (action.payload.Stop) {
        state.lastStop = action.payload.Stop;
      }
      if (action.payload.TogglePause) {
        state.lastTogglePause = action.payload.TogglePause;
      }
      if (action.payload.Command) {
        state.lastCommand = action.payload.Command;
      }
      if (action.payload.Seek) {
        state.lastSeek = action.payload.Seek;
      }
      if (action.payload.State) {
        state.lastState = action.payload.State;
        // Dispatch the new action to update SeriesState
        // Note: We can't directly dispatch here, so we'll need to handle this in the middleware
      }
      if (action.payload.Error) {
        state.lastError = action.payload.Error;
      }
      if (action.payload.SendLastState) {
        state.lastSendLastState = action.payload.SendLastState;
      }
      if (action.payload.LastState) {
        state.lastVideoDetails = action.payload.LastState;
      }
      if (action.payload.TaskStateChanged) {
        state.lastTaskState = action.payload.TaskStateChanged;
      }
      if (action.payload.CurrentTasks) {
        state.lastCurrentTasks = action.payload.CurrentTasks;
      }
      if (action.payload.Video) {
        state.pendingVideoEvents = [...(state.pendingVideoEvents ?? []), ...action.payload.Video];
      }
    },
  },
});

export const { dispatchRemoteMessage } = remoteMessageSlice.actions;

// Add a new thunk to handle the RemotePlayerState update
export const handleRemotePlayerState = (message: RemoteMessage) => (dispatch: any) => {
  if (message.State) {
    dispatch(updateActiveSeriesFromPlayerState(message.State));
  }
  if (message.Video && message.Video.length > 0) {
    dispatch(updateFromVideoEvent(message.Video));
  }
  dispatch(dispatchRemoteMessage(message));
};

export default remoteMessageSlice.reducer;

