/**
 * React Component that renders the control bar for the player.
 * @param {ControlsProps} props - The props object for the ControlBar component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlBar component.
 */
import React, { FC, useEffect, useRef, useState } from "react";
import { Affix, Button, Group, rem } from "@mantine/core";
import { 
  IconArrowLeftCircle, 
  IconArrowRightCircle, 
  IconMaximize, 
  IconMinimize,
  IconDoorExit,
  IconPlayerPlay,
  IconPlayerPause
} from "@tabler/icons-react";
import { AnalogClock, remToPx } from '@/components/Widgets/AnalogClock';


type ControlsProps = {
  seek: (interval: number) => void;
  togglePause?: () => void;
  quit: () => void;
  isPlaying?: () => boolean;
  currentlyPlaying?: boolean;
}

const SIZE_ICON = "3rem";
const COLOUR = "rgba(25, 113, 194, 0.7)"
const CLOCK_SIZE = 12;
const HIDE_DELAY = 7000;
const DOUBLE_TAP_DELAY = 300; // milliseconds between taps to be considered a double tap

export const Controls: FC<ControlsProps> = ({ seek, togglePause, isPlaying, currentlyPlaying, quit }) => {
  const [isFullScreen, setIsFullScreen] = useState<boolean>(false);
  const [isVisible, setIsVisible] = useState<boolean>(true);
  const timeoutRef = useRef<number | null>(null);
  const lastTapTimeRef = useRef<number>(0);
  
  const hideControls = () => {
    setIsVisible(false);
  };

  const tryTogglePause = () => {
    if (typeof(togglePause) !== "undefined") {
      togglePause();
    }
  }

  const tryIsPlaying = () => {
    if (typeof(isPlaying) !== "undefined") {
      return isPlaying();
    }
    return false;
  }

  const leave = (e?: React.MouseEvent<HTMLButtonElement>) => {
    e?.stopPropagation();
    if (tryIsPlaying()) {
      tryTogglePause();
    }
    quit();
  }

  const showControls = () => {
    setIsVisible(true);
    
    // Reset the timeout
    if (timeoutRef.current !== null) {
      window.clearTimeout(timeoutRef.current);
    }
    
    // Set a new timeout to hide controls after HIDE_DELAY seconds
    timeoutRef.current = window.setTimeout(hideControls, HIDE_DELAY);
  };
  
  // Handle double tap detection
  const handleTouchTap = (e: TouchEvent) => {
    const currentTime = new Date().getTime();
    const tapLength = currentTime - lastTapTimeRef.current;
    
    if (tapLength < DOUBLE_TAP_DELAY && tapLength > 0) {
      // Double tap detected
      e.preventDefault();
      tryTogglePause();
    }
    
    lastTapTimeRef.current = currentTime;
  };
  
  useEffect(() => {
    // Show controls initially with timeout
    showControls();
    
    // Set up event listeners for user interaction
    const handleUserInteraction = () => {
      showControls();
    };
    
    window.addEventListener('mousemove', handleUserInteraction);
    window.addEventListener('click', handleUserInteraction);
    window.addEventListener('keydown', handleUserInteraction);
    // Add touch event listeners
    window.addEventListener('touchstart', handleUserInteraction);
    window.addEventListener('touchmove', handleUserInteraction);
    
    // Add touch tap detection
    window.addEventListener('touchend', handleTouchTap);
    
    // Clean up
    return () => {
      if (timeoutRef.current !== null) {
        window.clearTimeout(timeoutRef.current);
      }
      window.removeEventListener('mousemove', handleUserInteraction);
      window.removeEventListener('click', handleUserInteraction);
      window.removeEventListener('keydown', handleUserInteraction);
      // Remove touch event listeners
      window.removeEventListener('touchstart', handleUserInteraction);
      window.removeEventListener('touchmove', handleUserInteraction);
      window.removeEventListener('touchend', handleTouchTap);
    };
  }, []);
  
  useEffect(() => {
    const handleFullScreenChange = () => {
      setIsFullScreen(!!document.fullscreenElement);
    };
    
    document.addEventListener('fullscreenchange', handleFullScreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullScreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      document.documentElement.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
    }
  };

  const topButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <ControlButton onClick={() => seek(-30)}>
        <IconArrowLeftCircle size={SIZE_ICON} />
      </ControlButton>
      <ControlButton onClick={tryTogglePause}>
        {currentlyPlaying ? <IconPlayerPause size={SIZE_ICON} /> : <IconPlayerPlay size={SIZE_ICON} />}
      </ControlButton>
      <ControlButton onClick={toggleFullScreen}>
        {isFullScreen ? <IconMinimize size={SIZE_ICON} /> : <IconMaximize size={SIZE_ICON} />}
      </ControlButton>
      <ControlButton onClick={() => seek(30)}>
        <IconArrowRightCircle size={SIZE_ICON} />
      </ControlButton>
    </Group>
  )

  const leftButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <ControlButton onClick={(e) => leave(e)}>
        <IconDoorExit size={SIZE_ICON} />
      </ControlButton>
    </Group>
  )

  const clockSize = remToPx(CLOCK_SIZE);

  const rightButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <AnalogClock 
        size={clockSize} 
        dialColor={COLOUR}
        digitalTimeFormat="12h"
      />
    </Group>
  )

  if (!isVisible) {
    return null;
  }

  return (
    <>
      <Affix 
        key="top-video-controls" 
        position={{ top: rem(100), left: '50%' }}
        sx={{ transform: 'translateX(-50%)' }}
      >
        {topButtons}
      </Affix>
      <Affix 
        key="left-video-controls" 
        position={{ top: '50%', left: rem(100) }}
        sx={{ transform: 'translateY(-50%)' }}
      >
        {leftButtons}
      </Affix>
      <Affix 
        key="right-video-controls" 
        position={{ top: '50%', right: rem(100) }}
        sx={{ transform: 'translateY(-50%)' }}
      >
        {rightButtons}
      </Affix>
    </>
  )
}

type ControlButtonProps = {
  children?: React.ReactNode;
  ariaLabel?: string;
  onClick: (e?: React.MouseEvent<HTMLButtonElement>) => void;
}

/**
 * React component that renders a control button to be used in the ControlBar.
 * @param {ControlButtonProps} props - The props object for the ControlButton component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlButton component.
 */
export const ControlButton = (props: ControlButtonProps) => {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>): void => {
    props.onClick(e);
  };
  return (
    <Button 
      size="xl" 
      variant="filled" 
      onClick={(e) => handleClick(e)}
      sx={{
        padding: '32px 48px',  // Increase padding for larger touchable area
        minWidth: '120px',      // Ensure minimum width
        height: 'auto',        // Allow height to adjust to content
        backgroundColor: COLOUR, // Semi-transparent blue
        '&:hover': {
          backgroundColor: 'rgba(25, 113, 194, 0.9)', // Less transparent on hover
        }
      }}
    >
      {props.children}
    </Button>
  )
}
