import {HiCloudDownload, HiSearch, HiVideoCamera} from "react-icons/hi";
import React from "react";
import { ActionIcon, Stack } from "@mantine/core";
import { useSelector } from "react-redux";
import { RootState } from "@/domain/Store";

/**
 * Defines properties of SpeedDialer component, including closeMenu(), an optional scrollTop number,
 * and the element to which the popup menu is attached
 */
type SpeedDialerProps = {
  showTasks: (() => void);
  showSearch: (() => void);
  showCurrentVideo: (() => void);
};


/**
 * Returns a floating button React component, like s speed dial button, with proper positioning, styling, and behavior.
 *
 * @param {SpeedDialerProps} props - Properties of SpeedDialer component, including closeMenu(), optional scrollTop,
 * and the element to which the popup menu is attached
 */
export const SpeedDialer = (props: SpeedDialerProps) => {
  const currentTasks = useSelector((state: RootState) => state.remote.lastCurrentTasks) ?? [];
  const lastState = useSelector((state: RootState) => state.remote.lastState);

  const tasksButton = (
    currentTasks.length !== 0 ?
    <ActionIcon onClick={() => props.showTasks()} color="blue" variant="filled" size="xl" radius="xl">
      <HiCloudDownload size="1.5rem" />
    </ActionIcon> :
    null
  );

  /**
   * Renders the popup menu with proper HTML structure and properties
   */
  return (
    <Stack style={{position: "fixed", right: "1em", bottom: "1em"}}>
      {tasksButton}
      <ActionIcon onClick={() => props.showSearch()} color="blue" variant="filled" size="xl" radius="xl">
        <HiSearch size="1.5rem" />
      </ActionIcon>
      <ActionIcon onClick={() => props.showCurrentVideo()} color="blue" variant="filled" size="xl" radius="xl">
        <HiVideoCamera size="1.5rem" />
      </ActionIcon>
    </Stack>
  );
}
